      "title": "マラーター同盟とデカン高原",
      "body": [
        "そして、イギリスに味方した諸侯の領地に<strong class=\"source-bold\">デカン高原</strong>から<strong class=\"source-bold\">マラーター同盟</strong>（ヒンドゥー教徒の諸侯同盟）が攻め込んでくると、今度はイギリスとマラーター同盟との戦争になった。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラーター戦争</strong></span>だ。マラーター同盟の側もイギリスに対抗して北インドに勢力を拡大し始めたから、もはやイギリスとの対立は避けられない！ しかし、この戦争でもイギリスはマラーター同盟内での内紛を利用して戦い、同盟は崩壊……<strong class=\"source-bold\">イギリスがデカン高原を征服</strong>したんだ。"
      ],
      "plainBody": [
        "そして、イギリスに味方した諸侯の領地にデカン高原からマラーター同盟（ヒンドゥー教徒の諸侯同盟）が攻め込んでくると、今度はイギリスとマラーター同盟との戦争になった。これがマラーター戦争だ。マラーター同盟の側もイギリスに対抗して北インドに勢力を拡大し始めたから、もはやイギリスとの対立は避けられない！ しかし、この戦争でもイギリスはマラーター同盟内での内紛を利用して戦い、同盟は崩壊……イギリスがデカン高原を征服したんだ。"
      ],
