      "title": "英国の反撃と反乱軍の失速",
      "body": [
        "しかし、インド人の抵抗もここまでだ。反乱軍のなかには指揮官になれるような人物がいなかったから、だんだんと足並みが乱れて急速に勢いを失った。しかも、イギリスは<strong class=\"source-bold\">諸侯たちを再び裏切らせ</strong>、さらに周辺諸国（<strong class=\"source-bold\">アフガン人やネパールのグルカ人</strong>など）からの軍も使い、使える人や物は全部使って反撃した。"
      ],
