      "body": [
        "結局、1858年には<strong class=\"source-bold\">ムガル皇帝が捕えられて、ビルマに<ruby>流刑<rt>るけい</rt></ruby></strong>となった。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムガル帝国の滅亡</strong></span>だよ。そして、反乱の責任を取らせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社の解散</strong></span>が決まり、インドは<strong class=\"source-bold\">イギリス本国政府の直接<ruby>統治<rt>とうち</rt></ruby>になった</strong>。"
      ],
