      "title": "直接統治と藩王国の自治",
      "body": [
        "インド大反乱の鎮圧後、イギリスは本国政府の直接<ruby>統治<rt>とうち</rt></ruby>によってインドの統治をつくり変えていったよ。結局、<strong class=\"source-bold\">インドのほうが人口も多いし領域も広い</strong>から、軍隊の力だけで抑えこむのはムリだよ。だったら、現地の人間も支配に取り込んじゃえばいい。反乱前は<strong class=\"source-bold\"><ruby>藩王国<rt>はんおうこく</rt></ruby></strong>（<ruby>諸侯<rt>しょこう</rt></ruby>たちね）を取り潰して<ruby>併合<rt>へいごう</rt></ruby>してきたけど、むしろ<strong class=\"source-bold\">藩王国をそのまま残して自治権を与え、間接統治をする</strong>ことにした。"
      ],
      "plainBody": [
        "インド大反乱の鎮圧後、イギリスは本国政府の直接統治によってインドの統治をつくり変えていったよ。結局、インドのほうが人口も多いし領域も広いから、軍隊の力だけで抑えこむのはムリだよ。だったら、現地の人間も支配に取り込んじゃえばいい。反乱前は藩王国（諸侯たちね）を取り潰して併合してきたけど、むしろ藩王国をそのまま残して自治権を与え、間接統治をすることにした。"
      ],
