      "id": "modern-c02-l08-p02-002",
      "title": "英語公用語と行政官制度",
      "body": [
        "イギリスは、ペルシア語に変えて<strong class=\"source-bold\">英語を公用語にする</strong>と、<strong class=\"source-bold\">インド人エリートを養成して官僚として支配に取り込む制度</strong>（インド高等行政官制度【<strong class=\"source-bold\">ICS</strong>】）をつくったんだ。背景には、インドにおける<strong class=\"source-bold\">民族資本</strong>の成長があるよ。"
      ],
      "plainBody": [
        "イギリスは、ペルシア語に変えて英語を公用語にすると、インド人エリートを養成して官僚として支配に取り込む制度（インド高等行政官制度【ICS】）をつくったんだ。背景には、インドにおける民族資本の成長があるよ。"
      ],
