      "title": "ナオロジーとバネルジーの民族運動",
      "body": [
        "一方で、<strong class=\"source-bold\">近代教育を受けたインドの知識人たちは民族運動に目覚め始めた</strong>。<strong class=\"source-bold\">ナオロジー</strong>はインドが貧困になっている原因は「<strong class=\"source-bold\">イギリスへの富の流出</strong>だ！」って主張し、理由もなく高等文官職を解雇された<strong class=\"source-bold\">バネルジー</strong>は裁判における<strong class=\"source-bold\">人種差別に反対</strong>して<strong class=\"source-bold\">全インド国民協議会</strong>を結成、<strong class=\"source-bold\">参政権を要求する運動</strong>を始めたんだ。"
      ],
      "plainBody": [
        "一方で、近代教育を受けたインドの知識人たちは民族運動に目覚め始めた。ナオロジーはインドが貧困になっている原因は「イギリスへの富の流出だ！」って主張し、理由もなく高等文官職を解雇されたバネルジーは裁判における人種差別に反対して全インド国民協議会を結成、参政権を要求する運動を始めたんだ。"
      ],
