      "id": "modern-c02-l08-p03-014",
      "title": "契約移民と複合社会",
      "body": [
        "また、イギリスは鉱山やプランテーション開発の際に<strong class=\"source-bold\">中国商人（華僑）を利用</strong>したから、彼らと同郷の中国人の<ruby>貧困<rt>ひんこん</rt></ruby>層が<strong class=\"source-bold\">契約移民「<ruby>苦力<rt>クーリー</rt></ruby>」</strong>として大量に流入し低賃金労働者となった。こうして、マレー半島では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">華僑</strong></span>が増加し、<strong class=\"source-bold\">支配層のイギリス人と下層のマレー人の間に中間層の中国人</strong>が存在する複合社会が形成されたんだよ。同じような現象は、このあとに話すインドネシアなどでも見られるね。"
      ],
      "plainBody": [
        "また、イギリスは鉱山やプランテーション開発の際に中国商人（華僑）を利用したから、彼らと同郷の中国人の貧困層が契約移民「苦力」として大量に流入し低賃金労働者となった。こうして、マレー半島では華僑が増加し、支配層のイギリス人と下層のマレー人の間に中間層の中国人が存在する複合社会が形成されたんだよ。同じような現象は、このあとに話すインドネシアなどでも見られるね。"
      ],
