      "id": "modern-c02-l08-p03-017",
      "title": "フランスとの関係と清への朝貢",
      "body": [
        " これで、ヨーロッパ諸国のなかだとフランスがベトナムへの優先権を持つことになったけど、伝統的に<strong class=\"source-bold\">ベトナムの王朝は中国王朝に朝貢している</strong>から、<strong class=\"source-bold\">阮朝も清に朝貢した</strong>。つまり、ベトナムは清の<ruby>属国<rt>ぞっこく</rt></ruby>になったってことだ。"
      ],
