        " これで、ヨーロッパ諸国のなかだとフランスがベトナムへの優先権を持つことになったけど、伝統的にベトナムの王朝は中国王朝に朝貢しているから、阮朝も清に朝貢した。つまり、ベトナムは清の属国になったってことだ。"
