      "title": "サイゴン条約とコーチシナ東部",
      "body": [
        "こうして結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイゴン条約</strong></span>では、<strong class=\"source-bold\">コーチシナ東部</strong>3省と<strong class=\"source-bold\">サイゴン</strong>が<strong class=\"source-bold\">フランスに割譲</strong>され、<strong class=\"source-bold\">キリスト教布教の自由</strong>が認められたんだ。あっ、この時フランスが取った<strong class=\"source-bold\">コーチシナ東部</strong>ってのは、メコン川の河口に広がる<strong class=\"source-bold\">メコン・デルタ</strong>の一部（デルタってのは、河口付近の三角州のこと）だよ。"
      ],
      "plainBody": [
        "こうして結ばれたサイゴン条約では、コーチシナ東部3省とサイゴンがフランスに割譲され、キリスト教布教の自由が認められたんだ。あっ、この時フランスが取ったコーチシナ東部ってのは、メコン川の河口に広がるメコン・デルタの一部（デルタってのは、河口付近の三角州のこと）だよ。"
      ],
