      "body": [
        "中国進出を狙うフランスは、メコン川を上っても中国には行けないことがわかると、今度はベトナム北部の<ruby>紅河<rt>こうが</rt></ruby>【ホン川】に注目し、<strong class=\"source-bold\">トンキン</strong>（ベトナム北部）から中国南部の<ruby>雲南<rt>うんなん</rt></ruby>への<strong class=\"source-bold\">進出</strong>を狙ったよ。"
      ],
