      "id": "modern-c02-l08-p03-031",
      "title": "インドシナ連邦とラオスの編入",
      "body": [
        "ベトナム支配を確立したフランスは、1887年、<strong class=\"source-bold\">ベトナム（トンキン、アンナン、コーチシナ）</strong>と<strong class=\"source-bold\">カンボジア</strong>を合わせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ連邦</strong></span>を成立させたよ。のちに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラオス</strong></span>のルアンプラバン王国も保護国化して<strong class=\"source-bold\">インドシナ連邦に編入</strong>し、<strong class=\"source-bold\">フランスのインドシナ支配が確立した</strong>んだ。"
      ],
      "plainBody": [
        "ベトナム支配を確立したフランスは、1887年、ベトナム（トンキン、アンナン、コーチシナ）とカンボジアを合わせてフランス領インドシナ連邦を成立させたよ。のちにラオスのルアンプラバン王国も保護国化してインドシナ連邦に編入し、フランスのインドシナ支配が確立したんだ。"
      ],
