      "title": "ジャワ返還とスマトラの勢力圏",
      "body": [
        "この間、ジャワ島には一時イギリスの<strong class=\"source-bold\">ラッフルズが進出</strong>したけど、ウィーン体制下でオランダに返還され、さらに1824年の<strong class=\"source-bold\">イギリス＝オランダ協定</strong>で<strong class=\"source-bold\">オランダがスマトラ島を確保</strong>し、ほぼ現在のインドネシアを勢力範囲にしたんだね。"
      ],
      "plainBody": [
        "この間、ジャワ島には一時イギリスのラッフルズが進出したけど、ウィーン体制下でオランダに返還され、さらに1824年のイギリス＝オランダ協定でオランダがスマトラ島を確保し、ほぼ現在のインドネシアを勢力範囲にしたんだね。"
      ],
