      "title": "ファン＝デン＝ボスと強制栽培制度",
      "body": [
        "そこでオランダは、<strong class=\"source-bold\">ジャワ戦争鎮圧の戦費とベルギー独立</strong>で悪化した財政を立て直すために、<strong class=\"source-bold\">ジャワ島</strong>で東インド<ruby>総督<rt>そうとく</rt></ruby><strong class=\"source-bold\">ファン＝デン＝ボス</strong>の主導により<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">強制栽培制度</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政府栽培制度</strong></span><strong class=\"source-bold\">】</strong>を実施した。"
      ],
