      "id": "modern-c02-l08-p03-050",
      "title": "アチェ戦争とオランダ領東インド",
      "body": [
        "1824年の<strong class=\"source-bold\">イギリス＝オランダ協定</strong>で<strong class=\"source-bold\">スマトラ島を勢力圏</strong>にしたオランダは、19世紀後半には<strong class=\"source-bold\">スマトラ島北端</strong>まで進出し、1912年には<strong class=\"source-bold\">アチェ王国</strong>を征服（<strong class=\"source-bold\">アチェ戦争</strong>）して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オランダ領東インド</strong></span>が完成したよ。これが現在の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア</strong></span>だ。"
      ],
      "plainBody": [
        "1824年のイギリス＝オランダ協定でスマトラ島を勢力圏にしたオランダは、19世紀後半にはスマトラ島北端まで進出し、1912年にはアチェ王国を征服（アチェ戦争）して、オランダ領東インドが完成したよ。これが現在のインドネシアだ。"
      ],
