      "title": "教育を受けたエリートとブディ＝ウトモ",
      "body": [
        "オランダも現地の金持ちに<strong class=\"source-bold\">オランダ語で近代教育を受けさせてエリートを養成</strong>し、官僚として支配に利用したよ。でも、彼らはオランダ支配にはやっぱり不満。こうした知識人が<strong class=\"source-bold\">ジャワ人の地位向上などを目指して結成</strong>したのが、<strong class=\"source-bold\">ブディ＝ウトモ</strong>だ（「最高の英知」って意味ね）。"
      ],
