      "title": "船と往来が運ぶパン＝イスラーム主義",
      "body": [
        "こんなふうに、ジャワ島では人びとが結集するシンボルが「イスラーム教」になったんだけど、その背景には「<strong class=\"source-bold\">パン＝イスラーム主義</strong>」があるよ。当時、<strong class=\"source-bold\">蒸気船の発達とスエズ運河の開通</strong>で、西アジアと東南アジアを結ぶ船が頻繁に行き来するようになり、ジャワ島からメッカに行ったり、西アジアを経由してヨーロッパに行ったりする人が増えてたんだね。だから、<strong class=\"source-bold\">西アジアで広がっていた「パン＝イスラーム主義」がジャワ島にまで影響を与えた</strong>んだよ。"
      ],
      "plainBody": [
        "こんなふうに、ジャワ島では人びとが結集するシンボルが「イスラーム教」になったんだけど、その背景には「パン＝イスラーム主義」があるよ。当時、蒸気船の発達とスエズ運河の開通で、西アジアと東南アジアを結ぶ船が頻繁に行き来するようになり、ジャワ島からメッカに行ったり、西アジアを経由してヨーロッパに行ったりする人が増えてたんだね。だから、西アジアで広がっていた「パン＝イスラーム主義」がジャワ島にまで影響を与えたんだよ。"
      ],
