      "title": "マニラ開港と大土地所有制",
      "body": [
        "<strong class=\"source-bold\">スペイン領</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>は、1834年に<strong class=\"source-bold\">マニラを各国に開港</strong>したのち、プランテーションでの<strong class=\"source-bold\">サトウキビ・マニラ麻・タバコ</strong>などの生産が拡大した。商人たちは「輸出で<ruby>儲<rt>もう</rt></ruby>けるぞ！」と開発を進めたから、<strong class=\"source-bold\">大土地所有制が成立</strong>したんだ。"
      ],
      "plainBody": [
        "スペイン領だったフィリピンは、1834年にマニラを各国に開港したのち、プランテーションでのサトウキビ・マニラ麻・タバコなどの生産が拡大した。商人たちは「輸出で儲けるぞ！」と開発を進めたから、大土地所有制が成立したんだ。"
      ],
