export const sourcePages = {
  "140": "<h2>140</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">近代のインド・東南アジア</strong></span></h1>\n<p>それじゃあ近代の<strong class=\"source-bold\">アジア</strong>の2回目、今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">インドと東南アジア</strong></u>だよ。インドと東南アジアは、19世紀末には<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ほとんどが<ruby>列強<rt>れっきょう</rt></ruby>の植民地になってしまう</strong></u>んだけど、なんでそんなことになっちゃったんだろ？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド</strong></span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">イギリスのインド侵略</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">141〜145ページ</span></td></tr><tr><td></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">インド民族運動の始まり</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">145〜147ページ</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東南アジア</strong></span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">列強の東南アジア侵略</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">148〜158ページ</span></td></tr></tbody></table></div>\n<blockquote><p>次々と植民地にされていくインドと東南アジア……最後に残るのはどこだ？</p></blockquote>\n<p>18世紀の英仏による激しい植民地戦争を終えて<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イギリスがインド支配を確立</strong></u>すると、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">インドはイギリスにとって最も重要な植民地</strong></u>となり、イギリスの支配に苦しめられるよ。そして<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">民族運動が始まる</strong></u>と……今度は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヒンドゥー教徒とイスラーム教徒の対立が起こった</strong></u>。<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">東南アジアでも</strong></u>、イギリスだけじゃなくて、フランス、オランダ、そしてアメリカの進出に対抗して<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">民族運動が少しずつ芽生える</strong></u>んだ。</p>\n<p>それじゃあ、インドと東南アジアの始まり〜。</p>",
  "141": "<h2>141</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イギリスのインド侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">イギリスのインド侵略</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">イギリスによるインド征服</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> 東インド会社が拠点を建設</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マドラス</strong></span> [1639]、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボンベイ</strong></span> [1661]、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ</strong></span> [1690]</p>\n<p>※フランスは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポンディシェリ</strong></span> [1674]、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シャンデルナゴル</strong></span> [1673]</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> 英仏植民地戦争 <span data-source-color=\"green\" style=\"color:#315837\">→</span>イギリスがフランスに勝利し、インドでの優位を確立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>北インド……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラッシーの戦い</strong></span>[1757] <span data-source-color=\"green\" style=\"color:#315837\">→</span>東インド会社書記<strong class=\"source-bold\">クライヴ</strong>の活躍</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>南インド……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーナティック戦争</strong></span> [1744〜48／50〜54／58〜61(63)]</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> イギリスのインド征服</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マイソール戦争</strong></span> [1767〜99の間に4回] <span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">南インド</strong>を制圧</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラーター戦争</strong></span> [1775〜1818の間に3回] <span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">デカン高原</strong>中西部を制圧</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シク戦争</strong></span> [1845〜49の間に2回] <span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">ほぼ全インドの征服完了</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シパーヒーの反乱</strong></span> <span data-source-color=\"green\" style=\"color:#315837\">→</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド大反乱</strong></span> [1857〜59] に発展</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムガル帝国滅亡</strong></span> [1858] ……最後の皇帝をビルマに<ruby>流刑<rt>るけい</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社解散</strong></span>[1858]……インドは<strong class=\"source-bold\">イギリス本国政府の直接<ruby>統治<rt>とうち</rt></ruby></strong>となる</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド帝国</strong></span>の成立 [1877] ……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディズレーリ</strong></span>内閣による</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィクトリア女王</strong></span>を<strong class=\"source-bold\">インド皇帝</strong>とする。<strong class=\"source-bold\"><ruby>直轄地<rt>ちょっかつち</rt></ruby></strong>と大小550以上の<ruby>藩王<rt>はんおう</rt></ruby><ruby>国<rt>こく</rt></ruby>からなる</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">英仏植民地戦争はイギリスの完全勝利！</strong></span></h4>\n<p>まずは、<strong class=\"source-bold\">イギリスとフランスの植民地戦争</strong>をちょっとだけ確認しておこう。17世紀に、<strong class=\"source-bold\">イギリス</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マドラス</strong></span>（現在のチェンナイ）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボンベイ</strong></span>（現在のムンバイ）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ</strong></span>（現在のコルカタ）に、<strong class=\"source-bold\">フランス</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポンディシェリ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シャンデルナゴル</strong></span>に拠点を築いたけど、最初は都市に商館をつくる程度だったんだよ。そして英仏両国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社</strong></span>に特権を与えて貿易の<ruby>覇権<rt>はけん</rt></ruby>を争った。当時は<strong class=\"source-bold\">インド産<ruby>綿布<rt>めんぷ</rt></ruby></strong>が重要な商品だったからね。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">シャンデルナゴル</strong></td><td>(仏)</td></tr><tr><td><strong class=\"source-bold\">カルカッタ</strong></td><td>(英)</td></tr><tr><td><strong class=\"source-bold\">ボンベイ</strong></td><td>(英)</td></tr><tr><td><strong class=\"source-bold\">マドラス</strong></td><td>(英)</td></tr><tr><td><strong class=\"source-bold\">ポンディシェリ</strong></td><td>(仏)</td></tr></tbody></table></div>\n<p>てか、<strong class=\"source-bold\">インド産綿布？</strong> どういうこと？って思うかもね。当時、<strong class=\"source-bold\">ヨーロッパでつくっていた織物っていえば毛織物</strong>。要はウールだよ。今じゃセーターとかコートと</p>",
  "142": "<h2>142</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p>か、アウターとして着るよね。直接肌に触れたらチクチクで気分悪い……。それは当時の人だって一緒だよ。だから、<strong class=\"source-bold\">肌触りのいい<ruby>木綿<rt>もめん</rt></ruby>の人気が上がって</strong>きたんだ。ってことは、売れば<ruby>儲<rt>もう</rt></ruby>かる。「じゃあ、<strong class=\"source-bold\">インドから<ruby>綿布<rt>めんぷ</rt></ruby>を輸入して</strong>、ヨーロッパで売ろう！」って、<strong class=\"source-bold\">英仏は次々と貿易の拠点を建設</strong>したんだ。</p>\n<p>そして18世紀に入ると、<strong class=\"source-bold\">英仏はインドでの<ruby>覇権<rt>はけん</rt></ruby>をめぐって激しく争った</strong>よね。まずヨーロッパで起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア<ruby>継承<rt>けいしょう</rt></ruby>戦争</strong></span>と同時期に、南インドで<strong class=\"source-bold\">カーナティック戦争</strong>が始まった。初期にはフランスのインド<ruby>総督<rt>そうとく</rt></ruby><strong class=\"source-bold\">デュプレクス</strong>の活躍で、<strong class=\"source-bold\">フランスが優勢だった時期</strong>もあるんだけど、財政難とかフランスの貴族の<ruby>妬<rt>ねた</rt></ruby>みなんかもあって、<strong class=\"source-bold\">デュプレクスは本国に呼び戻された</strong>よ。もしデュプレクスがそのままインドに残っていたら……フランスがインドを取っていたかもしれないよ！。</p>\n<p>でも、歴史はそうは進まなかった。デュプレクスがいなくなったインドでは、今度は<strong class=\"source-bold\">イギリス東インド会社の書記</strong>だった<strong class=\"source-bold\">クライヴ</strong>が、フランスを追い詰めていった。ん？ もしかして、ちょっと疑問が浮かんだかもね。なんで東インド会社の書記なんだろ？</p>\n<p>当時の貿易会社って、自分たちの船やら拠点を守るために軍隊を持っていたんだよ。東インド会社は、もちろん陸軍も海軍も持っている！ だから、<strong class=\"source-bold\">イギリスは東インド会社の軍隊をインド<ruby>侵略<rt>しんりゃく</rt></ruby>に使った</strong>んだよ。そしてヨーロッパで起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">七年戦争</strong></span>と同時期に<strong class=\"source-bold\">北インド</strong>で起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラッシーの戦い</strong></span> [1757] では、<strong class=\"source-bold\">クライヴ</strong>の活躍によって<strong class=\"source-bold\">イギリス東インド会社軍がフランスとベンガル<ruby>太<rt>たい</rt></ruby><ruby>守<rt>しゅ</rt></ruby>の連合軍を破り</strong>、北インドからフランスを追い出した。さらに<strong class=\"source-bold\">南インド</strong>で続いていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーナティック戦争</strong></span>でもイギリスが勝利して、<strong class=\"source-bold\">イギリスがフランスに完全勝利した</strong>んだ。ここからはイギリスが、次々とインド征服を進めていくよ。</p>\n<blockquote><p>七年戦争期の植民地戦争は、北米のフレンチ＝インディアン戦争も一緒におさえておこう！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスのインド征服は、南から北へ</strong></span></h4>\n<p><strong class=\"source-bold\">アウラングゼーブ帝の死後</strong>、各地の<ruby>諸侯<rt>しょこう</rt></ruby>の反抗で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムガル帝国</strong></span>はすでに衰退して<strong class=\"source-bold\">分裂状態</strong>だったから、インドのなかには強国はなかった。だからイギリスは、インドの諸侯たちに「イギリスの味方をするなら、君たちの支配はそのまま認めてやろう」との甘い言葉をかけ、<strong class=\"source-bold\">イギリスの味方になった諸侯たちの軍隊をインド征服に使った</strong>よ。ここからは必ず地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➜P.143</strong></span>と一緒に見よう！ <strong class=\"source-bold\">イギリスのインド征服</strong>では3つの戦争があるんだけど、<strong class=\"source-bold\">始まった順番は「南から北」、終わったのも「南から北」</strong>だよ。そして、征服を進めたのは植民地戦争と同じ<strong class=\"source-bold\">東インド会社軍</strong>だ。まず東部では、<strong class=\"source-bold\">ブクサールの戦い</strong> [1764] でムガル皇帝やベンガル太守の連合軍を破って、翌年には<strong class=\"source-bold\">ベンガル地方などの徴税権・司法権を手に入れた</strong>。その</p>",
  "143": "<h2>143</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イギリスのインド侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>後、<strong class=\"source-bold\">南インドのヒンドゥー教国マイソール王国</strong>と戦った4次にわたる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マイソール戦争</strong></span>で、イギリスは現地の勢力の対立を利用しながら有利に戦いを進め、<strong class=\"source-bold\">マイソール王国を征服</strong>したよ。そして、イギリスに味方した諸侯の領地に<strong class=\"source-bold\">デカン高原</strong>から<strong class=\"source-bold\">マラーター同盟</strong>（ヒンドゥー教徒の諸侯同盟）が攻め込んでくると、今度はイギリスとマラーター同盟との戦争になった。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラーター戦争</strong></span>だ。マラーター同盟の側もイギリスに対抗して北インドに勢力を拡大し始めたから、もはやイギリスとの対立は避けられない！ しかし、この戦争でもイギリスはマラーター同盟内での内紛を利用して戦い、同盟は崩壊……<strong class=\"source-bold\">イギリスがデカン高原を征服</strong>したんだ。この時点で、イギリスに敵対しているのは<strong class=\"source-bold\">パンジャーブ地方のシク王国</strong>だけになった。しかし、イギリスの敵じゃない……。1845年に始まる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シク戦争</strong></span>で、<strong class=\"source-bold\">イギリスがパンジャーブ地方を征服</strong>したよ。こうして、<strong class=\"source-bold\">イギリスはインド全域の支配権を確立</strong>したんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">シク王国</strong></td><td></td></tr><tr><td>デリー</td><td></td></tr><tr><td><strong class=\"source-bold\">ムガル帝国</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">マラーター同盟</strong></td><td></td></tr><tr><td>カルカッタ</td><td>(英)</td></tr><tr><td>ボンベイ</td><td>(英)</td></tr><tr><td>マドラス</td><td>(英)</td></tr><tr><td><strong class=\"source-bold\">マイソール王国</strong></td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスの支配がインドの社会をぶち壊した！</strong></span></h4>\n<p>イギリスのインド支配によって、<strong class=\"source-bold\">インド社会は大きな打撃を受けた</strong>よ。まずイギリスは、<strong class=\"source-bold\">国内の産業資本家の要求</strong>もあって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社の貿易独占権を廃止</strong></span>したよね。1813年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">対インド貿易独占権が廃止</strong></span>され、1833年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">対中国貿易独占権も廃止</strong></span>され、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">すべての商業活動を停止</strong></span>されたから、イギリスの民間商人はインドとの貿易が自由にできるようになった。これにより、植民地インドには産業革命が進んだ<strong class=\"source-bold\">イギリス本国の機械製綿布</strong>が入ってきて、インドはイギリス木綿工業の<strong class=\"source-bold\">原料供給地、製品販売市場</strong>となっちゃった。18世紀までは綿布の輸出国だったインドでは、<strong class=\"source-bold\">イギリス製品の大量流入</strong>で<strong class=\"source-bold\">綿織物手工業が崩壊</strong>し、<strong class=\"source-bold\">失業者が増加</strong>したよ。一方、貿易独占権を失った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社</strong></span>は、これまでもインドを統治していたから、そのまま<strong class=\"source-bold\">インド統治機関として残った</strong>んだ。</p>\n<p><strong class=\"source-bold\">もはや貿易では儲けられない東インド会社</strong>はインドでの<strong class=\"source-bold\">徴税権【ディーワーニー】</strong>を持っていたから、効率的に税を集めるため<strong class=\"source-bold\">近代的な地租制度を導入</strong>したんだ。まず、あいまいだった土地所有権を誰か一人に認めて、所有権を持つ人から税金を取ることにした。そして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベンガル</strong></span><strong class=\"source-bold\">地方を中心とする北インド</strong>（ベンガル管区）では、もともとの支配階級だった<strong class=\"source-bold\">各地の地主や領主（ザミンダール）</strong>に土地所有権を認めるかわりに地税を納めさせる<strong class=\"source-bold\">ザミンダーリー制</strong>を導入、一方、<strong class=\"source-bold\">南インドや西インド</strong>（マドラス管区やボンベイ管区）では実際に耕作している<strong class=\"source-bold\">農民（ライヤット）</strong>に土地所有権を認めて税金を納めさせ、<strong class=\"source-bold\">農民を直接支配するライヤットワーリー制</strong>を導入したんだ。</p>",
  "144": "<h2>144</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p>ただ、土地所有権が誰か一人に決まってしまうと、農村では「貧乏だけど、みんなで助け合おう〜！」という意識が薄くなってくる。だって、土地を持っているヤツらは「ここはオレの土地だ！ オマエらが貧乏だろうとそんなもん知らん」って言い出すんだもん。だから、貧乏な人はどんどん貧乏になり、<strong class=\"source-bold\">伝統的な農村共同体が崩壊してしまった</strong>んだ。しかも、イギリスの商人たちが<strong class=\"source-bold\">プランテーション</strong>を導入して<strong class=\"source-bold\">輸出用の茶や<ruby>藍<rt>あい</rt></ruby>、アヘンなどの栽培</strong>を始めると、インドの産業は壊滅してしまったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">シパーヒーの反乱をきっかけに、インド大反乱が起きた！</strong></span></h4>\n<p>イギリス支配によるインド社会の崩壊をもう一度まとめておこう。イギリス製品の流入で<strong class=\"source-bold\">伝統的な手工業（特に綿織物手工業）が崩壊</strong>し、近代的な<ruby>地租<rt>ちそ</rt></ruby>の導入で<strong class=\"source-bold\">農村共同体が破壊</strong>され、さらに<strong class=\"source-bold\">プランテーションの導入</strong>でインドの<strong class=\"source-bold\">産業構造そのものが壊滅的な打撃</strong>を受けた。もう、インド人の不満は爆発寸前だ！</p>\n<p>そして、<strong class=\"source-bold\">東インド会社のインド人<ruby>傭兵<rt>ようへい</rt></ruby></strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シパーヒー</strong></span>）が起こした<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シパーヒーの反乱</strong></span>をきっかけに、<strong class=\"source-bold\">インド全域で次々と反乱が起こり</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド大反乱</strong></span>に発展したよ。反乱軍はイギリス軍の将校を殺害すると、<strong class=\"source-bold\">ムガル皇帝</strong>（バハードゥル＝シャー2世）<strong class=\"source-bold\">を<ruby>擁立<rt>ようりつ</rt></ruby></strong>、皇帝はイギリスへ<ruby>宣戦布告<rt>せんせんふこく</rt></ruby>した。こうなるともはや植民地の反乱ではなく、<strong class=\"source-bold\">インド（ムガル帝国）vs. イギリスの戦い</strong>だよ。そして、イギリスに協力していたはずの<ruby>諸侯<rt>しょこう</rt></ruby>たちも次々に反乱軍に加わり、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デリー</strong></span>を<ruby>占拠<rt>せんきょ</rt></ruby>した。そして、「イギリス支配から解放される」って思った<strong class=\"source-bold\">農民や都市の民衆も反乱に加わった</strong>から、反乱はインドのおよそ3分の2の地域にまで広がったんだよ。</p>\n<h3><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-bold\">α</strong></span>ちょっと寄り耳</strong></h3>\n<blockquote><p>イギリス東インド会社のインド人傭兵<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シパーヒー</strong></span>は、<strong class=\"source-bold\">クシャトリヤ</strong>（ヒンドゥー教徒の<strong class=\"source-bold\">上級カースト</strong>だ）や<strong class=\"source-bold\">イスラーム教徒</strong>が中心だったんだけど、もともと白人将校との差別にずっと不満だった。そしてデリー近郊のメーラト基地で「新型銃の弾丸を包んでいる油紙に、<strong class=\"source-bold\">豚と牛の油が使われている</strong>」って<ruby>噂<rt>うわさ</rt></ruby>が広まったから、さぁ大変！ 油紙は口で噛み切らなきゃいけなかったから、牛を食べちゃいけないヒンドゥー教徒と、豚を食べちゃいけないイスラーム教徒は、銃を撃つたびに<ruby>戒律<rt>かいりつ</rt></ruby>違反！ 「もう我慢ならん」と彼らは反乱を起こしたんだ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シパーヒーの反乱</strong></span>が各地に飛び火して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド大反乱</strong></span>に発展すると、各地の諸侯も次々と反乱に加わった。</p>\n<p>この時、反乱のシンボルとされたのが、インドのジャンヌ＝ダルクとも<ruby>称<rt>たた</rt></ruby>えられる若き<ruby>王妃<rt>おうひ</rt></ruby><strong class=\"source-bold\">ラクシュミー＝バーイ</strong>だ。彼女はサリーから男装に着替えて馬にまたがり、剣を振りかざして最後まで徹底的にイギリスに抵抗したんだけど、最後は戦死してしまった。のちの初代インド首相ネルーは彼女を「名声は群を抜き、今もって人びとの敬愛をあつめている人物」と言ってる。今ではインドの英雄として、各地に彼女の像が建てられてるよ。</p></blockquote>",
  "145": "<h2>145</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インド民族運動の始まり</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">反乱軍の抵抗もここまで……イギリスのインド支配の完成！</strong></span></h4>\n<p>しかし、インド人の抵抗もここまでだ。反乱軍のなかには指揮官になれるような人物がいなかったから、だんだんと足並みが乱れて急速に勢いを失った。しかも、イギリスは<strong class=\"source-bold\">諸侯たちを再び裏切らせ</strong>、さらに周辺諸国（<strong class=\"source-bold\">アフガン人やネパールのグルカ人</strong>など）からの軍も使い、使える人や物は全部使って反撃した。結局、1858年には<strong class=\"source-bold\">ムガル皇帝が捕えられて、ビルマに<ruby>流刑<rt>るけい</rt></ruby></strong>となった。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムガル帝国の滅亡</strong></span>だよ。そして、反乱の責任を取らせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東インド会社の解散</strong></span>が決まり、インドは<strong class=\"source-bold\">イギリス本国政府の直接<ruby>統治<rt>とうち</rt></ruby>になった</strong>。こうなると、もはやこれまでだ……。地方での反乱は続いたものの、<strong class=\"source-bold\">1859年には完全に<ruby>鎮圧<rt>ちんあつ</rt></ruby>されてしまった</strong>んだ。</p>\n<blockquote><p>ムガル帝国の滅亡と東インド会社の解散は、どちらも反乱を完全に鎮圧する前だよ！</p></blockquote>\n<p>インド大反乱の鎮圧後、イギリスは本国政府の直接<ruby>統治<rt>とうち</rt></ruby>によってインドの統治をつくり変えていったよ。結局、<strong class=\"source-bold\">インドのほうが人口も多いし領域も広い</strong>から、軍隊の力だけで抑えこむのはムリだよ。だったら、現地の人間も支配に取り込んじゃえばいい。反乱前は<strong class=\"source-bold\"><ruby>藩王国<rt>はんおうこく</rt></ruby></strong>（<ruby>諸侯<rt>しょこう</rt></ruby>たちね）を取り潰して<ruby>併合<rt>へいごう</rt></ruby>してきたけど、むしろ<strong class=\"source-bold\">藩王国をそのまま残して自治権を与え、間接統治をする</strong>ことにした。さらに、イギリスとインドの間に電信が敷かれたことから、インドの統治に関する決定はすべて本国政府と議会がおこない、本国にインド省とインド大臣が設置されたんだ。そして、1877年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディズレーリ</strong></span>内閣の時に、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィクトリア女王</strong></span>を<strong class=\"source-bold\">インド皇帝</strong>として、<strong class=\"source-bold\"><ruby>直轄地<rt>ちょっかつち</rt></ruby></strong>と大小550以上の<strong class=\"source-bold\">藩王国</strong>からなる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド帝国</strong></span>（英領インド）が成立した。現地のインドには、インド政府を<ruby>統括<rt>とうかつ</rt></ruby>するイギリス人の総督と参事会が置かれたよ。</p>\n<p>あっ！ 特に正誤問題で気をつけてほしいんだけど、インド帝国のなかには<strong class=\"source-bold\">自治権を認められた藩王国が残っている</strong>から、「<strong class=\"source-bold\">すべて直轄地</strong>」ってなってたら誤文だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">インド民族運動の始まり</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリス支配のなかから、民族運動が生まれた！</strong></span></h4>\n<p>インド大反乱の際にヒンドゥー教徒もイスラーム教徒も関係なくイギリスに反抗したことから、彼らのなかに<strong class=\"source-bold\">イギリス人に対する「インド人」という意識が生まれ</strong>、またイギリスの統治制度が変わったことで、インド人にも変化をもたらしたよ。イギリスは、ペルシア語に変えて<strong class=\"source-bold\">英語を公用語にする</strong>と、<strong class=\"source-bold\">インド人エリートを養成して官僚として支配に取り込む制度</strong>（インド高等行政官制度【<strong class=\"source-bold\">ICS</strong>】）をつくったんだ。背景には、インドにおける<strong class=\"source-bold\">民族資本</strong>の成長があるよ。</p>\n<p>民族資本ってのは、イギリス人に対抗して商業で活躍したり、綿工業などに投資して富を蓄えた<strong class=\"source-bold\">インド人の資本家</strong>のことだ。イギリスは彼らを支配に取り込むため</p>",
  "146": "<h2>146</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p>に大学を設置したり、本国へ留学させたりしたから、<strong class=\"source-bold\">近代教育を受けたインド人</strong>がどんどん増えていた。インド支配では「血と皮膚の色はインド人だが、趣味と意見と道徳、知においてはイギリス人であるような通訳的な階層をつくる」っていう、インド人にとってゾッとするような目標が掲げられていたんだ！。反面で、<strong class=\"source-bold\">イギリス資本の進出で工場が建設される</strong>と、インド人労働者は低賃金で働かされ、旧来の<strong class=\"source-bold\">地主の支配によって下層農民は<ruby>貧困<rt>ひんこん</rt></ruby>化していた</strong>。こうした下層民衆の不満もどんどん高まっていたんだよ。これに対してイギリスは、<strong class=\"source-bold\">カースト間の対立をあおって</strong>インド人の分断を図ったんだ。</p>\n<p>一方で、<strong class=\"source-bold\">近代教育を受けたインドの知識人たちは民族運動に目覚め始めた</strong>。<strong class=\"source-bold\">ナオロジー</strong>はインドが貧困になっている原因は「<strong class=\"source-bold\">イギリスへの富の流出</strong>だ！」って主張し、理由もなく高等文官職を解雇された<strong class=\"source-bold\">バネルジー</strong>は裁判における<strong class=\"source-bold\">人種差別に反対</strong>して<strong class=\"source-bold\">全インド国民協議会</strong>を結成、<strong class=\"source-bold\">参政権を要求する運動</strong>を始めたんだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">インド民族運動の展開</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド国民会議</strong></span>の結成 [1885] ……第1回大会は<strong class=\"source-bold\">ボンベイ</strong>で開催</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>当初は、商人や知識人による<strong class=\"source-bold\">親英的な組織</strong>（<strong class=\"source-bold\">ヒンドゥー教徒</strong>中心）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベンガル分割令</strong></span>【<strong class=\"source-bold\">カーゾン法</strong>】 [1905]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">ベンガル州</strong>を<strong class=\"source-bold\">ヒンドゥー教徒、イスラーム教徒の居住地域に分割</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span>反英闘争が激化。<strong class=\"source-bold\">国民会議では反英の急進派が主導権を握る</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議カルカッタ大会</strong></span>[1906]……<strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争における日本の勝利</strong>の影響</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティラク</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ大会4<ruby>綱領<rt>こうりょう</rt></ruby></strong></span></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英貨<ruby>排斥<rt>はいせき</rt></ruby></strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワデーシ</strong></span>（国産品愛用）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワラージ</strong></span>（自治）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族教育</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span>国民会議は、反英政治組織の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>となった</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span> [1906] ……<strong class=\"source-bold\">イギリスの支援</strong>で結成。<strong class=\"source-bold\">親英的</strong></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">民族運動をごまかしてしまえ！ インド国民会議が結成された</strong></span></h4>\n<p>民族運動の高揚に対し、イギリスはインドの知識人たちを<strong class=\"source-bold\">ボンベイ</strong>に集めて<strong class=\"source-bold\">インド人の不満をそらすために</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インド国民会議</strong></span>を結成した。ここには<strong class=\"source-bold\">ナオロジーも参加して議長となり</strong>、<strong class=\"source-bold\">バネルジーの全インド国民協議会も合流</strong>した。国民会議に参加した商人や地主、知識人たちは、最初は、「優秀なみなさんの意見を聞きたい」とおだてられていたから、<strong class=\"source-bold\">国民会議はかなり親英的だった</strong>。でも、イスラーム教徒は「インド国民とは“ヒンドゥー・ネーション”だろ」と反対して参加しなかった。だから<strong class=\"source-bold\">国民会議はヒンドゥー教徒が中心</strong>の組織になったんだ。そして、国民会議の大会は場所を変えながら毎年開かれたんだけど、参加者は頭が良かったから、自分</p>",
  "147": "<h2>147</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">インド民族運動の始まり</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>たちがイギリスの植民地支配に利用されてるんじゃないかって気づき始めたよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">民族運動を宗教で分断！ ベンガル分割令が出されると……</strong></span></h4>\n<p>そこでイギリスは、インドの民族運動を抑え込むために、「<strong class=\"source-bold\">インド人をヒンドゥー教徒とイスラーム教徒に分断しよう！</strong>」って考えて、もともと民族運動の激しかった<strong class=\"source-bold\">ベンガル州</strong>（カルカッタの周辺）を<strong class=\"source-bold\">ヒンドゥー教徒の居住地域とイスラーム教徒の居住地域に分割する</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベンガル分割令</strong></span>【カーゾン法】を発表したんだ。表向きは効率的に税金を集めるための処置ってことにはなってたけど、インド人には自分たちを分断するものにしか見えなかったから、完全にインド人を怒らせた。</p>\n<p>そして、同じ年に<strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争で日本が勝利</strong>するとインドでも民族運動が盛り上がり、翌1906年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティラク</strong></span>を指導者として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議カルカッタ大会</strong></span>が開かれ、<strong class=\"source-bold\">反英的な</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ大会4綱領</strong></span>を採択した。これは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英貨排斥</strong></span>（イギリス製品ボイコット）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワデーシ</strong></span>（国産品愛用）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワラージ</strong></span>（自治）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族教育</strong></span>の4つからなり、このスローガンのもとで<strong class=\"source-bold\">イギリス支配からの解放を目指す運動</strong>がおこなわれたよ。そして「もうイギリスに協力なんてしない！」と思った<strong class=\"source-bold\">ヒンドゥー教徒の国民会議は反英の政治組織</strong>（政党って考えていいよ）になって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>へと変貌したんだ。</p>\n<p>でも、こういう時にズルいことをすぐに思いつくのがイギリスだよ。イギリスは「ヒンドゥーがダメなら、<strong class=\"source-bold\">ヒンドゥー教徒と仲の悪いイスラーム教徒を味方にすればいい</strong>」って考えて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>の結成を支援したんだよ。イギリスは国民会議派の運動を抑えたいし、インドのなかで少数派の<strong class=\"source-bold\">ムスリム</strong>は、<strong class=\"source-bold\">イギリスに接近することで自分たちの政治的な権利を守りたい</strong>、ってことで「反ヒンドゥー」で意見が一致しちゃったんだね。これ以後イギリスは<strong class=\"source-bold\">ヒンドゥー教、イスラーム教の宗教対立をあおり、民族運動を分断</strong>していくんだ。そして、反英運動が盛んな<strong class=\"source-bold\">カルカッタからデリーに首都が移された</strong>よ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">インドの政治団体</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>……<u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">ヒンドゥー教徒</strong></u>が中心</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>創設当初の国民会議は<u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">親英的</strong></u>で<ruby>穏健<rt>おんけん</rt></ruby>な組織<span data-source-color=\"green\" style=\"color:#315837\">→</span>徐々に<strong class=\"source-bold\">反英</strong>に転じる</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ大会4綱領</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ティラク</strong></span>の指導で、<strong class=\"source-bold\">完全に反英となる</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英貨排斥</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワデーシ</strong></span>（国産品愛用）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スワラージ</strong></span>（自治）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族教育</strong></span></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>反英政治組織（政党）の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民会議派</strong></span>となった</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">全インド＝ムスリム連盟</strong></span>……<u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">イスラーム教徒</strong></u>が中心</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><strong class=\"source-bold\">イギリスの支援</strong>で結成した、<u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\"><strong class=\"source-bold\">親英的</strong></u>な組織</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span>ヒンドゥー教徒・イスラーム教徒の<strong class=\"source-bold\">宗教対立をあおって、民族運動を分断</strong></p></blockquote>",
  "148": "<h2>148</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">列強の東南アジア侵略</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>ビルマ</td><td></td></tr><tr><td>ハノイ</td><td></td></tr><tr><td>ベトナム</td><td></td></tr><tr><td>ラオス</td><td></td></tr><tr><td>フエ（ユエ）</td><td></td></tr><tr><td>タイ</td><td></td></tr><tr><td><strong class=\"source-bold\">フランス領インドシナ連邦</strong></td><td></td></tr><tr><td>カンボジア</td><td></td></tr><tr><td>サイゴン</td><td></td></tr><tr><td><strong class=\"source-bold\">フィリピン</strong></td><td>（1898年以降アメリカ領）</td></tr><tr><td>ペナン</td><td></td></tr><tr><td>マラッカ</td><td></td></tr><tr><td><strong class=\"source-bold\">マレー連合州</strong></td><td></td></tr><tr><td>シンガポール</td><td></td></tr><tr><td>スマトラ島</td><td></td></tr><tr><td>カリマンタン（ボルネオ）島</td><td></td></tr><tr><td><strong class=\"source-bold\">オランダ領東インド</strong></td><td></td></tr><tr><td>バタヴィア</td><td></td></tr><tr><td>ジャワ島</td><td></td></tr><tr><td>ティモール</td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"salmon\" style=\"color:#f3978c\">■</span></td><td>イギリス領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"gray-green\" style=\"color:#b6bdac\">■</span></td><td>フランス領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pale-pink\" style=\"color:#f5c6c5\">■</span></td><td>オランダ領</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"dark-green\" style=\"color:#617c5b\">■</span></td><td>スペイン領</td></tr><tr><td><span data-source-marker=\"hatch\" data-source-color=\"black\" style=\"color:#222222\">▨</span></td><td>ポルトガル領</td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td><td>イギリス海峡植民地</td></tr></tbody></table></div>\n<blockquote><p>東南アジアがどこの国の植民地になったか、地図と一緒に確認しよう！</p></blockquote>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">イギリスのマレー半島進出</em></strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">インドと中国をつなげ！ イギリスがマレー半島に進出</strong></span></h4>\n<p>それじゃあ<strong class=\"source-bold\">東南アジア</strong>に進むよ。まずは、<strong class=\"source-bold\">イギリス</strong>が進出した<strong class=\"source-bold\">マレー半島</strong>だ。インド支配を確立したイギリスは、中国との貿易を拡大するために、<strong class=\"source-bold\">インドと中国を結ぶ交易路を確保</strong>しよう！って考えた。そうなると、<strong class=\"source-bold\">中継点として重要なのは東南アジア</strong>だから、貿易船がどうやって<strong class=\"source-bold\">マラッカ海峡</strong>を安全に航行するかが重要になってくる。つまり、<strong class=\"source-bold\">安全な港を確保する</strong>ってことだ。</p>\n<p>そこでイギリスは、1786年にマラッカ海峡のインド洋からの入り口に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペナン島</strong></span>を確保した。さらに、<strong class=\"source-bold\">ヨーロッパでのナポレオン戦争</strong>のドサクサに紛れて、もともと<strong class=\"source-bold\">オランダ領</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラッカ</strong></span>を<ruby>占領<rt>せんりょう</rt></ruby>したんだ。これまでイギリスは、フランスと対抗するためにオランダとは仲良くやっていたから、オランダ領に攻め込むってことはあまりなかったんだけど、<strong class=\"source-bold\">革命中にフランスがオランダを征服した</strong>から、オランダ領を攻撃しても「フランスを弱らせてるんだ！」ってごまかせる。だからナポレオン戦争中に、<strong class=\"source-bold\">オランダ領のケープ植民地、セイロン島</strong>、そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マラッカ</strong></span>を占領した</p>",
  "149": "<h2>149</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">列強の東南アジア侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>んだ。そして、<strong class=\"source-bold\">ウィーン議定書でケープ植民地とセイロン島はイギリス領</strong>になったけど、マラッカは気づかなかったことにした。だって、「イギリスが得しすぎだろ！」って突っ込まれても困るでしょ。</p>\n<p>実を言うとイギリスは、<strong class=\"source-bold\">ナポレオン戦争中にジャワ島も占領している</strong>んだよ。これはイギリスの植民地行政官<strong class=\"source-bold\">ラッフルズ</strong>が強行したんだけど、<strong class=\"source-bold\">ナポレオンの失脚後にオランダに返還</strong>することになった。ラッフルズは「絶対返すな！」って主張したんだけど本国政府が返還を決めちゃったから、「だったら、バタヴィアよりもすごい拠点をつくってやる！」って思って、現地の<strong class=\"source-bold\">ジョホール王から強引に獲得</strong>した島が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シンガポール</strong></span>だよ。</p>\n<p>ラッフルズは、シンガポールに商人を集めるため、「<strong class=\"source-bold\">シンガポールは<ruby>関税<rt>かんぜい</rt></ruby>をかけない自由港</strong>にします！」って宣言した。これを聞いて「シンガポールのほうが得だぞ！」と思った<strong class=\"source-bold\">中国商人（<ruby>華僑<rt>かきょう</rt></ruby>）が集まり</strong>、バタヴィアを抜いて<strong class=\"source-bold\">東南アジア最大の貿易拠点</strong>になったよ。ちなみに、<strong class=\"source-bold\">現在のシンガポールに中国系住民が多い</strong>のも、この政策の<ruby>名残<rt>なごり</rt></ruby>だよ。こうしてイギリスは、<strong class=\"source-bold\">マレー半島では貿易港を確保して（<ruby>港市<rt>こうし</rt></ruby>支配）、自由貿易によって</strong>利益を上げる政策をとったんだよ。</p>\n<p>そして、1824年に結ばれた<strong class=\"source-bold\">イギリス＝オランダ協定</strong>によって、<strong class=\"source-bold\">マラッカ海峡を境界にマレー半島はイギリス、スマトラ島はオランダの勢力圏</strong>になったから、1826年、イギリスは<strong class=\"source-bold\">ペナン、マラッカ、シンガポール</strong>を合わせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">海峡植民地</strong></span>としたよ。</p>\n<blockquote><p>イギリスは、自由貿易を軸に、世界の<ruby>覇権<rt>はけん</rt></ruby>を握ったよね。<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第2回</strong></span>で話したパクス＝ブリタニカだ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">資源開発が始まると、領域を支配するマレー連合州が成立</strong></span></h4>\n<p>さて、貿易拠点として繁栄していたマレー半島が大きく変わっていくのは19世紀半ばだよ。当時、世界的に缶詰に使うブリキの需要が高まると、原料の<ruby>錫<rt>すず</rt></ruby>に注目が集まっていたんだ。そして、マレー半島で大きな<strong class=\"source-bold\">錫鉱脈が発見される</strong>とイギリスはマレー半島支配を拡大、単なる<strong class=\"source-bold\">港市支配から領域支配へと転換</strong>して、<strong class=\"source-bold\">錫鉱山の開発を進めた</strong>んだよ。そして、1895年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マレー連合州</strong></span>が成立し、マレー半島におけるイギリスの領域支配が完成したんだ（英領マレー）。</p>\n<p>さらに20世紀に入ると、<strong class=\"source-bold\">世界的な自動車産業の発達からゴムの<ruby>需要<rt>じゅよう</rt></ruby>が高まり</strong>、マレー連合州では<strong class=\"source-bold\">ゴム・プランテーション</strong>が拡大したよ。こうして、マレー半島は<strong class=\"source-bold\">世界的な錫と天然ゴムの生産地</strong>になった。また、イギリスは鉱山やプランテーション開発の際に<strong class=\"source-bold\">中国商人（華僑）を利用</strong>したから、彼らと同郷の中国人の<ruby>貧困<rt>ひんこん</rt></ruby>層が<strong class=\"source-bold\">契約移民「<ruby>苦力<rt>クーリー</rt></ruby>」</strong>として大量に流入し低賃金労働者となった。こうして、マレー半島では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">華僑</strong></span>が増加し、<strong class=\"source-bold\">支配層のイギリス人と下層のマレー人の間に中間層の中国人</strong>が存在する複合社会が形成されたんだよ。同じような現象は、このあとに話すインドネシアなどでも見られるね。また、マレー半島はイギリス領だったから、英領インド</p>",
  "150": "<h2>150</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p>から<strong class=\"source-bold\">インド人低賃金労働者（<ruby>印僑<rt>いんきょう</rt></ruby>）</strong>も流入したよ。</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">フランスのインドシナ進出</em></strong></span></h4>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">フランスのインドシナ進出</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ナポレオン3世の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ出兵</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\"><ruby>仏越<rt>ふつえつ</rt></ruby>戦争</strong> [1858〜62] ……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>阮<rt>げん</rt></ruby>朝</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>越南<rt>えつなん</rt></ruby></strong></span> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国</strong></span>]）に勝利</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイゴン条約</strong></span> [1862] ……<strong class=\"source-bold\">コーチシナ東部とサイゴン</strong>をフランスに<ruby>割譲<rt>かつじょう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カンボジア保護国化</strong></span> [1863] <span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">コーチシナ西部</strong>の<ruby>占領<rt>せんりょう</rt></ruby> [1867]</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>第三共和政期のベトナム進出<span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">フランスが<ruby>劉永福<rt>りゅうえいふく</rt></ruby>の<ruby>黒旗<rt>こっき</rt></ruby>軍と阮朝を破る</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">トンキン</strong>占領 [1873／82]、<strong class=\"source-bold\">アンナン</strong>占領 [1883]</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フエ条約</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユエ条約</strong></span>】[1883／84] ……フランスが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム保護国化</strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">阮朝の<ruby>宗主国<rt>そうしゅこく</rt></ruby>である清朝と対立</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>清仏<rt>しんふつ</rt></ruby>戦争</strong></span> [1884〜85] <span data-source-color=\"green\" style=\"color:#315837\">→</span>フランスが清朝を破る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>天津<rt>てんしん</rt></ruby>条約</strong></span> [1885] ……<strong class=\"source-bold\">清がベトナム宗主権を放棄、仏のベトナム保護国化を承認</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ連邦</strong></span>成立 [1887]</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム</strong></span>（<strong class=\"source-bold\">コーチシナ、トンキン、アンナン</strong>）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カンボジア</strong></span>で形成</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▸</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラオス</strong></span>のルアンプラバン王国も<strong class=\"source-bold\">保護国化</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">→</span><strong class=\"source-bold\">インドシナ連邦に編入</strong> [1899]</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">フランス人の援助で阮朝が成立！ でも清に<ruby>朝貢<rt>ちょうこう</rt></ruby>した</strong></span></h4>\n<p>続いて、<strong class=\"source-bold\">フランス</strong>が進出した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム</strong></span>だ。19世紀初め、ベトナムでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>阮福映<rt>げんふくえい</rt></ruby></strong></span>【嘉隆帝】が<strong class=\"source-bold\">タイ・ラオス</strong>や<strong class=\"source-bold\">フランス人<ruby>宣教師<rt>せんきょうし</rt></ruby>ピニョー</strong>の<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby>の援助を受けて<strong class=\"source-bold\"><ruby>西山<rt>せいざん</rt></ruby>政権を滅ぼし</strong>、<strong class=\"source-bold\">フエ【ユエ】</strong>を都として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">阮朝</strong></span>を建てたよ。国号は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>越南<rt>ヴィエトナム</rt></ruby>（国）</strong></span>。ちなみに「<strong class=\"source-bold\">越南」のベトナム語読みが「ベトナム」</strong>だよ。気づいてた？ これで、ヨーロッパ諸国のなかだとフランスがベトナムへの優先権を持つことになったけど、伝統的に<strong class=\"source-bold\">ベトナムの王朝は中国王朝に朝貢している</strong>から、<strong class=\"source-bold\">阮朝も清に朝貢した</strong>。つまり、ベトナムは清の<ruby>属国<rt>ぞっこく</rt></ruby>になったってことだ。</p>\n<p>しかも、阮福映の死後、<strong class=\"source-bold\">阮朝はキリスト教を迫害</strong>し始めた。さすがに阮福映は宣教師ピニョーに助けてもらったから、キリスト教迫害ができなかったんだろうけど、死んだら関係ない……。しかも、この時期のフランスは<strong class=\"source-bold\">七月革命や二月革命</strong>などで国内が混乱していたから、ベトナム進出はしなかったんだよ。</p>",
  "151": "<h2>151</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">列強の東南アジア侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">人気取り皇帝のナポレオン3世がインドシナに出兵した！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span>が皇帝に即位すると<strong class=\"source-bold\">積極的に対外進出</strong>したよね。これまでフランスは、<strong class=\"source-bold\">アメリカ大陸やインドでイギリスに負けてる</strong>から、イギリスほど植民地はない……。ナポレオン3世としては、このへんでガッツリ植民地を獲得して、人気も一緒に取りたい！ こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドシナ出兵</strong></span>が始まったよ。</p>\n<p>1858年、<strong class=\"source-bold\">ナポレオン3世</strong>は<strong class=\"source-bold\">フランス人宣教師迫害</strong>を口実に、<strong class=\"source-bold\">アロー戦争に合わせて</strong>ベトナムに<ruby>侵攻<rt>しんこう</rt></ruby>し（<strong class=\"source-bold\">仏越戦争</strong>）、阮朝を破って南部（コーチシナ）の中心都市サイゴンを占領した。こうして結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイゴン条約</strong></span>では、<strong class=\"source-bold\">コーチシナ東部</strong>3省と<strong class=\"source-bold\">サイゴン</strong>が<strong class=\"source-bold\">フランスに割譲</strong>され、<strong class=\"source-bold\">キリスト教布教の自由</strong>が認められたんだ。あっ、この時フランスが取った<strong class=\"source-bold\">コーチシナ東部</strong>ってのは、メコン川の河口に広がる<strong class=\"source-bold\">メコン・デルタ</strong>の一部（デルタってのは、河口付近の三角州のこと）だよ。その後、ナポレオン3世はさらに支配を拡大し、1863年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カンボジアを保護国化</strong></span>すると、1867年には<strong class=\"source-bold\">コーチシナ西部</strong>も占領したよ。こうしてメコン・デルタを支配下に置いたフランスは、ここを「<strong class=\"source-bold\">輸出用のコメ生産の拠点</strong>」とし、<strong class=\"source-bold\">コメの輸出</strong>で<ruby>莫大<rt>ばくだい</rt></ruby>な利益を上げたんだ。当時、中国南部での人口増加や、東南アジア各地でコーヒーや砂糖などをつくるプランテーションが拡大して穀物生産が減少し、<strong class=\"source-bold\">世界的にコメの価格が上がっていた</strong>からね。フランスはボロ<ruby>儲<rt>もう</rt></ruby>けだったんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>メコン川</td><td></td></tr><tr><td>紅河</td><td></td></tr><tr><td>雲南</td><td></td></tr><tr><td>ハノイ</td><td></td></tr><tr><td>ラオス</td><td></td></tr><tr><td>トンキン</td><td></td></tr><tr><td>フエ</td><td></td></tr><tr><td>アンナン</td><td></td></tr><tr><td>カンボジア</td><td></td></tr><tr><td>サイゴン</td><td></td></tr><tr><td>コーチシナ</td><td></td></tr><tr><td>東部</td><td></td></tr><tr><td>西部</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">阮朝を助けた黒旗軍！ でもフランスには勝てず……</strong></span></h4>\n<p>中国進出を狙うフランスは、メコン川を上っても中国には行けないことがわかると、今度はベトナム北部の<ruby>紅河<rt>こうが</rt></ruby>【ホン川】に注目し、<strong class=\"source-bold\">トンキン</strong>（ベトナム北部）から中国南部の<ruby>雲南<rt>うんなん</rt></ruby>への<strong class=\"source-bold\">進出</strong>を狙ったよ。フランスの進出を抑えたい阮朝は、雲南にいた<strong class=\"source-bold\">劉永福</strong>の<strong class=\"source-bold\">黒旗軍</strong>に協力を求め、一緒にフランスと戦った。ちなみに、<strong class=\"source-bold\">黒旗軍</strong>は<strong class=\"source-bold\"><ruby>太平天国<rt>たいへいてんごく</rt></ruby>の残党の武装集団</strong>だよ。当初、<strong class=\"source-bold\">普仏</strong>戦争に敗戦した直後で余裕のなかったフランスは苦戦したんだけど、最終的には<strong class=\"source-bold\">阮朝と黒旗軍を破り</strong>、<strong class=\"source-bold\">トンキン</strong>（ベトナム北部）、<strong class=\"source-bold\">アンナン</strong>（ベトナム中部）を占領し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フエ条約</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユエ条約</strong></span>】を結んで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナムを保護国化</strong></span>したよ。</p>",
  "152": "<h2>152</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ベトナムの<ruby>宗主国<rt>そうしゅこく</rt></ruby>だった<ruby>清<rt>シン</rt></ruby>が怒って、<ruby>清仏<rt>しんふつ</rt></ruby>戦争が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p><strong class=\"source-bold\"><ruby>阮<rt>げん</rt></ruby>朝はもともと清に<ruby>朝貢<rt>ちょうこう</rt></ruby>する<ruby>属国<rt>ぞっこく</rt></ruby>（朝貢国）だった</strong>よね。でも、ヨーロッパの国から見ると、全く属国には見えない。なぜかというと、<strong class=\"source-bold\">阮朝には清朝の軍団も役人もいない</strong>からだ。ヨーロッパの国は保護国化すると必ず役人や軍隊を置いて、実際に支配していることが見えるようにしたんだけど（難しい言葉を使うと<strong class=\"source-bold\">実効支配</strong>ね）、朝貢の場合には<strong class=\"source-bold\">属国が清朝に使者を送るだけ</strong>だから、ヨーロッパ諸国が見ると「実効支配してないだろ」って思うんだよ。だから<strong class=\"source-bold\">フランスは清朝を無視してベトナムに進出</strong>したんだね。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">清</strong></td><td>宗主国</td></tr><tr><td><strong class=\"source-bold\">ベトナム</strong></td><td>属国</td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td><td><span data-source-marker=\"arrow\" data-source-color=\"black\" style=\"color:#222222\">↑</span> 保護国化</td></tr><tr><td><span data-source-marker=\"arrow\" data-source-color=\"green\" style=\"color:#859476\">↔</span></td><td><strong class=\"source-bold\">対立</strong></td></tr></tbody></table></div>\n<p>でも、いざ保護国化すると、清は「オレの属国に手を出すな〜！」って怒り、<strong class=\"source-bold\">フランスと清が対立</strong>した。こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">清仏戦争</strong></span>が勃発したよ。しかし開戦してみると、<ruby>専制<rt>せんせい</rt></ruby>政治のまま改革の進んでいない<strong class=\"source-bold\">清朝は劣勢となり、フランスに負けてしまった</strong>。結局、1885年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>天津<rt>てんしん</rt></ruby>条約</strong></span>が結ばれ、清は<strong class=\"source-bold\">宗主権を<ruby>放棄<rt>ほうき</rt></ruby></strong>して<strong class=\"source-bold\">フランスのベトナム保護国化を承認</strong>し、さらに清朝の南部数省（<ruby>雲南<rt>うんなん</rt></ruby>など）でのフランスの特権を承認した。</p>\n<p>ベトナム支配を確立したフランスは、1887年、<strong class=\"source-bold\">ベトナム（トンキン、アンナン、コーチシナ）</strong>と<strong class=\"source-bold\">カンボジア</strong>を合わせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ連邦</strong></span>を成立させたよ。のちに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラオス</strong></span>のルアンプラバン王国も保護国化して<strong class=\"source-bold\">インドシナ連邦に編入</strong>し、<strong class=\"source-bold\">フランスのインドシナ支配が確立した</strong>んだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ベトナムでは、日本への憧れから<ruby>東遊<rt>ドンズー</rt></ruby>運動が始まった！</strong></span></h4>\n<p>フランスに植民地化されたベトナムの知識人たちのなかには、<strong class=\"source-bold\">日本への憧れ</strong>が広がっていた。それは<strong class=\"source-bold\">日本が<ruby>明治維新<rt>めいじいしん</rt></ruby>によって近代化に成功</strong>し、欧米文化を受け入れつつ<strong class=\"source-bold\">植民地化されずに独立を維持</strong>していたからだよ。こうした知識人の一人だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファン＝ボイ＝チャウ</strong></span>は、日本をお手本にしてフランス支配からの解放を目指したよ。彼はもともと<ruby>科挙<rt>かきょ</rt></ruby>に合格した官僚だったんだけど、フランスによる植民地化で、自分の国も、<ruby>儒学<rt>じゅがく</rt></ruby>を基盤にした自分の価値観も、根底からひっくり返されちゃった。そこで彼は<strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争中に維新会を結成</strong>し、<strong class=\"source-bold\">日露戦争で日本が勝利</strong>すると、日本から軍事援助を得ようとする活動を進めたり、日本の近代化を学ぶために<strong class=\"source-bold\">日本に留学生を送る</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東遊運動</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドンズー運動</strong></span><strong class=\"source-bold\">】</strong></p>\n<blockquote><p>日露戦争の影響がまた出てきたよ！ 日露戦争がむちゃくちゃ大事って、わかってきたかな？</p></blockquote>",
  "153": "<h2>153</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">列強の東南アジア侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>を始めたりしたよ。きっと、日本がロシアに勝ったのと同じように、自分たちがフランス支配から解放されるのを夢見ていたんだね。</p>\n<p>しかし、1907年に<strong class=\"source-bold\">日仏協約</strong>が結ばれると、フランス政府は日本に「ベトナムの留学生を取り締まってくれ！」と要請し、<strong class=\"source-bold\">日本政府もやむなく取り締まりを強化</strong>したから、<strong class=\"source-bold\">東遊運動は挫折</strong>してしまった……。日本としても、すでに三国協商が成立しているから、フランスを怒らせると英仏露の3国が敵になるからね。でも<strong class=\"source-bold\">ファン＝ボイ＝チャウはあきらめない！</strong> 今度は<strong class=\"source-bold\">中国の<ruby>辛亥<rt>しんがい</rt></ruby>革命</strong>に刺激を受け、<ruby>広<rt>カン</rt></ruby><ruby>東<rt>トン</rt></ruby>で<strong class=\"source-bold\">ベトナム<ruby>光復<rt>こうふく</rt></ruby>会</strong>を設立して武力革命によるベトナム共和国の建設を目指した。でも、これも<ruby>弾圧<rt>だんあつ</rt></ruby>されて衰退してしまったんだ。やっぱ、独立運動って難しいね。</p>\n<p>一方で、同じ時期にファン＝ボイ＝チャウを批判して、<strong class=\"source-bold\">フランスと協力して近代化をやったほうが得だろ！</strong>って考えた人もいたよ。それが<strong class=\"source-bold\">ファン＝チュー＝チン</strong>だ。彼はハノイに<strong class=\"source-bold\">ドンキン義塾</strong>を設立して、ベトナム語のローマ字表記であるクォック＝グー（漢字だと「国語」）やフランス語を使った<ruby>啓蒙<rt>けいもう</rt></ruby>教育による近代化を目指したんだ。でも、フランスにしてみればベトナムは「<ruby>搾取<rt>さくしゅ</rt></ruby>するための植民地」に過ぎなかったから、<strong class=\"source-bold\">フランスの協力は得られず弾圧された</strong>んだよ。</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">オランダのインドネシア（東インド）進出</em></strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">東部のマタラム王国も征服して、オランダがジャワ島支配を確立！</strong></span></h4>\n<p>次は、<strong class=\"source-bold\">オランダ</strong>が進出した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア</strong></span>だよ。1623年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アンボイナ事件</strong></span>で<strong class=\"source-bold\">イギリスをマルク諸島【モルッカ諸島】から追い出す</strong>と、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オランダ東インド会社</strong></span>がジャワ島の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バタヴィア</strong></span>を拠点に<strong class=\"source-bold\"><ruby>香辛料<rt>こうしんりょう</rt></ruby>貿易を独占</strong>したよね。でも、17世紀に入ると世界の香辛料価格が急落してしまった。だからオランダは、香辛料をヨーロッパに持っていく貿易じゃなくて、<strong class=\"source-bold\">アジアの中継貿易で<ruby>儲<rt>もう</rt></ruby>ける</strong>ことにしたよ。さらに、<strong class=\"source-bold\">ジャワ島では東部にも支配を拡大</strong>し、18世紀に入ると<strong class=\"source-bold\">マタラム王国</strong>を征服して、<strong class=\"source-bold\">ジャワ島全島の支配を確立</strong>したんだ。</p>\n<p>その後、フランス革命中に<strong class=\"source-bold\">オランダ東インド会社が解散</strong>すると、<strong class=\"source-bold\">ジャワ島はオランダ政府の直接<ruby>統<rt>とう</rt></ruby>治</strong>になったんだけど、オランダ本国がフランスに征服されちゃった。この間、ジャワ島には一時イギリスの<strong class=\"source-bold\">ラッフルズが進出</strong>したけど、ウィーン体制下でオランダに返還され、さらに1824年の<strong class=\"source-bold\">イギリス＝オランダ協定</strong>で<strong class=\"source-bold\">オランダがスマトラ島を確保</strong>し、ほぼ現在のインドネシアを勢力範囲にした</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イギリス＝オランダ協定 [1824]の境界</span></td><td><span data-source-marker=\"dashed-boundary\" data-source-color=\"red\" style=\"color:#e52715\">┄</span></td></tr><tr><td>アチェ</td><td></td></tr><tr><td>マラッカ</td><td></td></tr><tr><td>シンガポール</td><td></td></tr><tr><td>カリマンタン（ボルネオ）島</td><td></td></tr><tr><td>スマトラ島</td><td></td></tr><tr><td><strong class=\"source-bold\">オランダ領東インド</strong></td><td></td></tr><tr><td>マタラム</td><td></td></tr><tr><td>バタヴィア</td><td></td></tr><tr><td>ジャワ島</td><td></td></tr></tbody></table></div>",
  "154": "<h2>154</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p>んだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">オランダが実施した強制栽培制度で、ジャワ島が<ruby>飢饉<rt>ききん</rt></ruby>になった！</strong></span></h4>\n<p>オランダに返還されたあとのジャワ島では、<strong class=\"source-bold\">イギリスの進出による混乱</strong>に加えて、<strong class=\"source-bold\">オランダの支配強化に対する不満</strong>が高まり、1825年、ジャワ島の王族ディポネゴロを指導者とする<strong class=\"source-bold\">ジャワ戦争</strong>が起きた。この反乱は<ruby>鎮圧<rt>ちんあつ</rt></ruby>までに5年もかかったから、<strong class=\"source-bold\">オランダの植民地財政は破産寸前</strong>。しかも、本国にも財政的な余裕はない！ だって、1830年には<strong class=\"source-bold\">七月革命の影響でベルギーが独立</strong>したんだもん。ベルギーって「チョコレート」とか思っちゃダメよ。<strong class=\"source-bold\">フランドル地方を中心に工業が発展</strong>していたから、オランダの経済にとっては大打撃だ！</p>\n<p>そこでオランダは、<strong class=\"source-bold\">ジャワ戦争鎮圧の戦費とベルギー独立</strong>で悪化した財政を立て直すために、<strong class=\"source-bold\">ジャワ島</strong>で東インド<ruby>総督<rt>そうとく</rt></ruby><strong class=\"source-bold\">ファン＝デン＝ボス</strong>の主導により<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">強制栽培制度</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政府栽培制度</strong></span><strong class=\"source-bold\">】</strong>を実施した。これは、政府が土着の村落首長と契約し、農地に<strong class=\"source-bold\">コーヒー、サトウキビ、<ruby>藍<rt>あい</rt></ruby>（インディゴ）</strong>など、ヨーロッパ向けの<strong class=\"source-bold\">輸出用の商品作物の栽培を割り当てて強制栽培させ</strong>、決められた量を植民地政府が<ruby>市場<rt>しじょう</rt></ruby>よりも安い値段で買い上げる制度だ。これで<strong class=\"source-bold\">オランダの財政は急速に回復！</strong> なんと、1850年代のオランダの国家収入の3割以上が、この強制栽培制度からの利益だったんだ。</p>\n<p>この制度で働くジャワの農民は賃金をもらって少し豊かになったんだけど、人口が急増して食糧が足りなくなった。しかも、サトウキビ畑とかは増えるのに、<strong class=\"source-bold\">主食であるコメの生産が減少</strong>して、<strong class=\"source-bold\">ジャワ島では飢饉も起きた</strong>から、さすがに本国でも「政府の強制栽培で、飢饉を起こしてんだろ」っていう批判が出始めた。こうして1860年代以降、<strong class=\"source-bold\">強制栽培制度は利益の少ないものから廃止</strong>され、<strong class=\"source-bold\">民間が経営するプランテーションに転換されていった</strong>んだよ。</p>\n<p>あと難関大向けの補足ね！ 一番利益の多かった<strong class=\"source-bold\">コーヒーだけは1916年まで強制栽培制度が残った</strong>ので、全部が一気に廃止されたわけじゃないよ。</p>\n<blockquote><p>民間のプランテーションなら、政府の責任はない！ってことでしょ……ズルいな、これ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">スマトラ島にも支配が拡大。労働者として<ruby>華僑<rt>かきょう</rt></ruby>の流入も拡大！</strong></span></h4>\n<p>1824年の<strong class=\"source-bold\">イギリス＝オランダ協定</strong>で<strong class=\"source-bold\">スマトラ島を勢力圏</strong>にしたオランダは、19世紀後半には<strong class=\"source-bold\">スマトラ島北端</strong>まで進出し、1912年には<strong class=\"source-bold\">アチェ王国</strong>を征服（<strong class=\"source-bold\">アチェ戦争</strong>）して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オランダ領東インド</strong></span>が完成したよ。これが現在の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドネシア</strong></span>だ。</p>\n<p>スマトラ島では、マレー半島と同じように<strong class=\"source-bold\"><ruby>錫<rt>すず</rt></ruby>鉱山の開発が進み</strong>、さらに<strong class=\"source-bold\">コーヒーなどのプランテーション経営</strong>も始まった。これらの開発には多くの<strong class=\"source-bold\">中国商人</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">華</strong></span></p>",
  "155": "<h2>155</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">列強の東南アジア侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">僑</strong></span>）<strong class=\"source-bold\">がかかわっていた</strong>んだよ。ここでちょっと華僑の説明を補足しておこう！</p>\n<p>すでに<ruby>明<rt>みん</rt></ruby>代以降、<strong class=\"source-bold\">中国商人がバタヴィアなどを中心にジャワ島に進出</strong>し、貿易や現地の金融業に従事していた。オランダは<strong class=\"source-bold\">植民地支配に華僑を利用</strong>し（例えば徴税とかね）、近代に入ると<strong class=\"source-bold\">強制栽培制度の集荷</strong>なども華僑にやらせたんだ。さらに、<strong class=\"source-bold\">錫鉱山やプランテーションの開発</strong>にも金持ちの華僑を使ったから、低賃金労働者として<strong class=\"source-bold\">中国から契約移民「<ruby>苦力<rt>クーリー</rt></ruby>」が流入</strong>したよ。こうして、<strong class=\"source-bold\">ジャワ島やスマトラ島でも華僑が急増した</strong>んだよ。一方で、強制栽培制度やプランテーションで貧乏になった農民は、華僑の金融業者からお金を借りるしかなくなり、さらに現地のムスリム商人も華僑の商人に利益を奪われて、不満を持っていたから、<strong class=\"source-bold\">華僑と現地住民の対立</strong>が起きたんだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">インドネシアの民族運動はイスラーム教のもとに結集した！</strong></span></h4>\n<p>オランダも現地の金持ちに<strong class=\"source-bold\">オランダ語で近代教育を受けさせてエリートを養成</strong>し、官僚として支配に利用したよ。でも、彼らはオランダ支配にはやっぱり不満。こうした知識人が<strong class=\"source-bold\">ジャワ人の地位向上などを目指して結成</strong>したのが、<strong class=\"source-bold\">ブディ＝ウトモ</strong>だ（「最高の英知」って意味ね）。この運動は大規模な政治活動にはならなかったんだけど、このあと、状況が大きく変化するよ。</p>\n<p>1911年、<strong class=\"source-bold\">中国で<ruby>辛亥<rt>しんがい</rt></ruby>革命が起こる</strong>と、革命運動に資金援助をした<strong class=\"source-bold\">ジャワの華僑商人</strong>たちが「中国バンザイ！ ♪」みたいに盛り上がって、<strong class=\"source-bold\">華僑のナショナリズムが高揚</strong>したんだ。これを見たジャワの商人たちは怒った！ だって、彼らは商業の利益をめぐって華僑商人と対立しているんだもん。「だったらオレたちも団結してやろーじゃないの」って、<strong class=\"source-bold\">ジャワのムスリム商人の民族意識が高揚</strong>し、<strong class=\"source-bold\">華僑に対抗して</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サレカット＝イスラム</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラーム同盟</strong></span><strong class=\"source-bold\">】</strong>が結成された。この動きはたちまちジャワ島全体に拡大し、彼らは<strong class=\"source-bold\">オランダに対して自治権を要求する</strong>政治運動を始めたんだ。</p>\n<p>こんなふうに、ジャワ島では人びとが結集するシンボルが「イスラーム教」になったんだけど、その背景には「<strong class=\"source-bold\">パン＝イスラーム主義</strong>」があるよ。当時、<strong class=\"source-bold\">蒸気船の発達とスエズ運河の開通</strong>で、西アジアと東南アジアを結ぶ船が頻繁に行き来するようになり、ジャワ島からメッカに行ったり、西アジアを経由してヨーロッパに行ったりする人が増えてたんだね。だから、<strong class=\"source-bold\">西アジアで広がっていた「パン＝イスラーム主義」がジャワ島にまで影響を与えた</strong>んだよ。</p>\n<blockquote><p>第一次世界大戦後の民族運動でも、サレカット＝イスラムは重要だよ！</p></blockquote>",
  "156": "<h2>156</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">フィリピンの民族運動と米西戦争</em></strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ホセ＝リサールの独立運動。でもスペインに処刑された！</strong></span></h4>\n<p><strong class=\"source-bold\">スペイン領</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>は、1834年に<strong class=\"source-bold\">マニラを各国に開港</strong>したのち、プランテーションでの<strong class=\"source-bold\">サトウキビ・マニラ麻・タバコ</strong>などの生産が拡大した。商人たちは「輸出で<ruby>儲<rt>もう</rt></ruby>けるぞ！」と開発を進めたから、<strong class=\"source-bold\">大土地所有制が成立</strong>したんだ。そしてスペインも<strong class=\"source-bold\">エリートを養成して植民地支配に利用するため</strong>に、フィリピン人の本国への留学などを進めていた。しかし、<strong class=\"source-bold\">留学生たち</strong>は留学先のスペインで民族意識を高め、<strong class=\"source-bold\">植民地支配の改革などを求める言論活動</strong>（「プロパガンダ運動」）を始めたんだ。そんな知識人たちのなかで、改革ではなく<strong class=\"source-bold\">フィリピンの独立</strong>を説いたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホセ＝リサール</strong></span>だよ。</p>\n<p>ホセ＝リサールは、本国に留学中に<strong class=\"source-bold\">スペインの暴政を暴露する小説（「われにふれるな」）を書いて</strong>、「フィリピンに必要なのは独立だ」って主張し、逮捕されるのを覚悟してフィリピンに帰国すると、<strong class=\"source-bold\">フィリピン民族同盟</strong>を結成したよ。そしたら、<strong class=\"source-bold\">結成直後に本当に逮捕されちゃった</strong>。でも、彼の活動は確実にフィリピン人に「スペインから独立しなきゃいけない！」っていう民族意識を植えつけていたんだよ。</p>\n<blockquote><p>最初がホセ＝リサール、彼の処刑後がアギナルド。二人の出てくる順番をおさえよう！</p></blockquote>\n<p><strong class=\"source-bold\">ホセ＝リサールの逮捕をきっかけ</strong>に、フィリピンでは独立を目指す秘密結社<strong class=\"source-bold\">カティプーナン</strong>が結成された。そして、スペインにその存在がバレてしまうと、<strong class=\"source-bold\">フィリピン各地で一斉に反乱を起こした</strong>んだ。これが<strong class=\"source-bold\">フィリピン革命</strong>の始まりだよ。<strong class=\"source-bold\">ホセ＝リサールは</strong>「この反乱の<ruby>首謀者<rt>しゅぼうしゃ</rt></ruby>だ」って決めつけられて<strong class=\"source-bold\">処刑されてしまった</strong>んだけど、<strong class=\"source-bold\">リサールの処刑を機に</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アギナルド</strong></span><strong class=\"source-bold\">が革命政府をつくり</strong>、その大統領に就任した。ただ、スペインの攻撃はますます激しくなり、<strong class=\"source-bold\">アギナルドは<ruby>亡命<rt>ぼうめい</rt></ruby></strong>するしかなくなってしまったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アメリカに助けられた、と思ったら甘かった。フィリピン＝アメリカ戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p>1898年、<strong class=\"source-bold\">キューバの独立運動</strong>をきっかけに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>米西<rt>べいせい</rt></ruby>戦争</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ＝スペイン戦争</strong></span><strong class=\"source-bold\">】</strong>が始まると、アメリカ軍がフィリピンにきてスペイン艦隊を破ったよ。そして、アメリカは戦争を有利に進めるために、<strong class=\"source-bold\">アギナルドをアメリカの軍艦で帰国させた</strong>んだ。この時、フィリピンの人たちは、アメリカがアギナルドにフィリピン独立を約束してくれたって信じていたから、再び革命政府をつくり、<strong class=\"source-bold\">アギナルドを大統領</strong>とする<strong class=\"source-bold\">フィリピン共和国【マロロス共和国】</strong>を樹立したんだよ。</p>\n<p>そして、米西戦争後の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>で<strong class=\"source-bold\">アメリカ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>を<strong class=\"source-bold\">獲得</strong>することが決まったんだけど、<strong class=\"source-bold\">アメリカはフィリピン共和国を独立させる気なんか全くない</strong>。独立を<ruby>潰<rt>つぶ</rt></ruby>すためにフィリピンを攻撃し始め、<strong class=\"source-bold\">フィリピン＝アメリカ戦争</strong>が勃発、フィ</p>",
  "157": "<h2>157</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">列強の東南アジア侵略</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">列強の侵略とアジアの変革</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>リピン側もゲリラ戦で抵抗したんだけど、アメリカにはかなわなかった……結局、<strong class=\"source-bold\">アギナルドも逮捕されてしまった</strong>んだよ。そして、アギナルドは国民の前で「フィリピンはアメリカ領です……」っていう宣言をさせられて釈放された。これって、むちゃくちゃ屈辱だよね……。ちなみに、米西戦争とフィリピン＝アメリカ戦争は次の中国のところでも重要だから、しっかりおさえておこう！</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">タイの独立維持と近代化</em></strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">東南アジア唯一の独立国として残ったタイ。決め手は不平等条約？</strong></span></h4>\n<p>最後は<strong class=\"source-bold\">東南アジアで唯一独立を保った</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タイ</strong></span>だよ。1782年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラタナコーシン朝</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャクリ朝</strong></span><strong class=\"source-bold\">】</strong>が成立したころには、特別強かったわけでもない。一応、<ruby>華僑<rt>かきょう</rt></ruby>を保護して、<strong class=\"source-bold\">王室が独占する中国商人との貿易によって利益を上げていた</strong>けど、ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>に勝てるか？っていったら、たぶん勝てないよ。じゃあ、なんでタイだけ独立を維持できたんだろう？</p>\n<p>19世紀後半に即位した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラーマ4世</strong></span>は、若いころには出家して僧院にいたから、権力闘争とかに巻き込まれず、わりと自由にキリスト教の<ruby>宣教<rt>せんきょう</rt></ruby>師などと交流して、<strong class=\"source-bold\">英語も話せるようになった</strong>。だから、彼が僧から世俗に戻って即位した時、ヨーロッパ人たちは「ラーマ4世はヨーロッパ寄りの開明的な国王だ！」って思ったんだ。かといって、ヨーロッパ諸国の進出を完全に食い止められたわけじゃないけど、少なくとも、<strong class=\"source-bold\">彼は自分の意思を直接イギリスに伝えることができる！</strong> イギリスとの間では、<strong class=\"source-bold\">不平等条約</strong>である<strong class=\"source-bold\">ボーリング条約</strong>を結んで<strong class=\"source-bold\">自由貿易の原則</strong>を受け入れ、これによってイギリス政府との関係をつくり、<strong class=\"source-bold\">タイの独立と主権を主張し続けた</strong>。だからイギリスも「自由貿易ができるから植民地にしなくてもいいか」と思って、タイを征服しなかったんだよ。その後、欧米各国とも友好条約を結んでタイの経済を世界経済と結びつけ、子どもたちにはイギリス人の家庭教師をつけて近代教育を受けさせた。これ、映画「王様と私」のモデルだよ。</p>\n<blockquote><p>ラーマ4世は近代化の出発点、それを受け継いだのがラーマ5世だ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">タイの独立を維持したラーマ5世。英仏両国の思惑にも注目だ！</strong></span></h4>\n<p>そして、ラーマ4世の死後、長男の<strong class=\"source-bold\">チュラロンコン</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラーマ5世</strong></span>として即位した。彼は、王族を中心に近代的な<strong class=\"source-bold\">中央集権体制</strong>をつくってタイを近代国家に生まれ変わらせると、積極的に西欧文化を取り入れて、<strong class=\"source-bold\"><ruby>奴隷<rt>どれい</rt></ruby>制の廃止や教育制度の近代化</strong>などの改革を進めたんだ。でも、この時期はホントに難しい時代だったと思うよ。だって、タイの北方では<strong class=\"source-bold\">フランス領インドシナ連邦が成立</strong>し、さらに、<strong class=\"source-bold\">イギリス</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビルマ戦争</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンバウン朝</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラウンパヤー朝</strong></span><strong class=\"source-bold\">】</strong>を滅ぼし、さらに<strong class=\"source-bold\">ビルマをインド</strong></p>",
  "158": "<h2>158</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第8回</strong></span> 近代のインド・東南アジア</p>\n<p><strong class=\"source-bold\">帝国に<ruby>併合<rt>へいごう</rt></ruby></strong>したころだもん。東西から英仏両国に挟まれて、タイはいつ<ruby>侵略<rt>しんりゃく</rt></ruby>されてもおかしくなかったんだよ。ここでラーマ5世は本領発揮！ <strong class=\"source-bold\">イギリス、フランス両国と外交交渉をおこなって</strong>、いくらか領土は失ったもののなんとか<strong class=\"source-bold\">独立は維持した</strong>よ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">インド帝国</strong>（英）</td><td><span data-source-marker=\"arrow\" data-source-color=\"red\" style=\"color:#e52715\">↘</span></td></tr><tr><td>ハノイ</td><td></td></tr><tr><td><strong class=\"source-bold\">タイ</strong></td><td></td></tr><tr><td><strong class=\"source-bold\">フランス領インドシナ連邦</strong></td><td><span data-source-marker=\"arrow\" data-source-color=\"green\" style=\"color:#315837\">←</span></td></tr><tr><td><strong class=\"source-bold\">マレー連合州</strong>（英）</td><td></td></tr></tbody></table></div>\n<p>その後、英仏両国は「<strong class=\"source-bold\">新興国ドイツに対抗するために、両国の直接対決を避けよう</strong>」って決めたから、<strong class=\"source-bold\">タイは英仏の<ruby>緩衝<rt>かんしょう</rt></ruby>地帯</strong>（衝突を避けるために、あえて独立させておく地域）になった。この決定はもちろんタイには幸運だね。でもそれだけじゃなくて、ここまでの<strong class=\"source-bold\">近代化によってタイが独立国と認められていたこと</strong>も、独立が維持できた理由だよ。ちなみに、<strong class=\"source-bold\">ラーマ5世の治世と日本の明治天皇の治世はほぼ同じ時期</strong>なんだ。日本もタイも不平等条約に苦しんだものの、近代化で独立を維持したのは同じだね。</p>\n<p>さて、インドと東南アジアはこれでおしまい。最後に年号checkしておこう！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">‼</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">年号のツボ</em></strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">プラッシーの戦い</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1757</strong></span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>非<rt>1</rt></ruby><ruby>難<rt>7</rt></ruby><ruby>こ<rt>5</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>けりゃ インドへ侵略）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">シパーヒーの反乱（インド大反乱）<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1857</strong></span>]</p>\n<p>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>ご<rt>5</rt></ruby></strong></span>めん<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>な<rt>7</rt></ruby></strong></span> シパーヒー）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">インド帝国成立</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1877</strong></span>] （インド帝国 <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>人<rt>1</rt></ruby><ruby>は<rt>8</rt></ruby><ruby>泣<rt>7</rt></ruby></strong></span>く<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>泣<rt>7</rt></ruby></strong></span>く イギリス支配）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">インド国民会議の結成</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1885</strong></span>] （国民会議で <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>人<rt>1</rt></ruby></strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>や<rt>8</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>ご<rt>5</rt></ruby></strong></span>ねる）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">インド国民会議カルカッタ大会</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1906</strong></span>] （4<ruby>綱領<rt>こうりょう</rt></ruby>は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>特<rt>19</rt></ruby><ruby>例<rt>0</rt></ruby><ruby>無<rt>6</rt></ruby></strong></span>視）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>清仏<rt>しんふつ</rt></ruby>戦争勃発</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1884</strong></span>] （フランスが <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>夜<rt>8</rt></ruby><ruby>襲<rt>4</rt></ruby></strong></span>で <ruby>清<rt>シン</rt></ruby>倒す）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">フランス領インドシナ連邦成立</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1887</strong></span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>夜<rt>8</rt></ruby></strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>花<rt>87</rt></ruby></strong></span>咲く インドシナ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>米西<rt>べいせい</rt></ruby>戦争</strong> [<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1898</strong></span>] （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>キュー<rt>9</rt></ruby><ruby>バ<rt>8</rt></ruby></strong></span>へ 米西戦争）</p></blockquote>\n<p>次回から、<strong class=\"source-bold\">中国史</strong>を2回に分けて見ていくよ。<strong class=\"source-bold\">中国近現代史がアジア史では一番のヤマ場</strong>かな。勉強のペースはつかめてるかな？ 少し大変になってきたころかもしれないけど、志望校合格に向けて<ruby>頑張<rt>がんば</rt></ruby>っていこう〜。</p>"
};

